import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易尚氏学 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易尚氏学 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"zh/classics/shangshi/062.md","filePath":"zh/classics/shangshi/062.md"}'),s={name:"zh/classics/shangshi/062.md"};function h(t,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>初四皆承阳。故曰巽。巽顺也。顺阳故小亨。往遇阳故利。阳居二五得中。故利见大人。</p><p>彖日。重巽以申命。刚巽乎中正而志行。柔皆顺乎刚。是以小亨。利有攸往。利见大人。</p><p>巽为命令。虞书申命义叔。传申重也。重巽以申命者。谓工者一再宣布命令。以示郑重也。巽为风。行莫疾于风。命令一出。传达天下。有若于风。故巽为命也。二五中正。下阴顺承。故志行。</p><p>象曰。随风。巽。君子以申命行事。</p><p>重巽故曰随风。随继也。从也。言后风之随前风也。令出惟行。万事以治。故君子以之。</p><p>初六。进退。利武人之贞。</p><p>初临重阳得主。故宜于进。而四无应与。故进而又退。象释曰志疑。疑四无应也。震为武人。此巽卦也。何以利武人之占。因震巽相反复。巽究则为震。易贵将来。故武人利也。</p><h3 id="象曰。进退。志疑也。利武人之贞。志治也。" tabindex="-1">象曰。进退。志疑也。利武人之贞。志治也。 <a class="header-anchor" href="#象曰。进退。志疑也。利武人之贞。志治也。" aria-label="Permalink to “象曰。进退。志疑也。利武人之贞。志治也。”">​</a></h3><p>巽不果。故志疑。返震故志治。言得行其志以治天下。</p><p>九二。巽在床下。用史玉纷若。吉。无咎。</p><p>巽为床。初顺二。故曰巽在床下。初至四正覆兑。兑口多。故曰用史巫纷若。按周礼内史云。凡命诸侯孤卿大夫。则策命之。凡四方之事书。内史读之。仪礼云。辞多则史。又司巫云。男巫女巫。凡邦之大栽。则歌哭而请。是史巫皆以口舌为用。而二居正反兑之间。故曰纷若。纷若言不一也。二得中故吉无咎。此义先儒无知者。只茹敦和云。巽初之阴。伏于床下。震也。于是乎用史巫以祛之。史巫云者互兑也。象始大明。而茹氏仍不知初至三为覆兑。故纷若不得解。</p><h3 id="象曰。纷若之吉。得中也。" tabindex="-1">象曰。纷若之吉。得中也。 <a class="header-anchor" href="#象曰。纷若之吉。得中也。" aria-label="Permalink to “象曰。纷若之吉。得中也。”">​</a></h3><p>二无应。失位。遇敌。然下孚于阴得中故吉。</p><p>九三。频巽。吝。</p><p>王弼云。频。频蹙不乐。按玉篇颦下云。易本作频。是频即古文颦字。三居巽上。虽当位而下挠。故频蹙不安而吝也。</p><h3 id="象曰。频巽之吝。志穷也。" tabindex="-1">象曰。频巽之吝。志穷也。 <a class="header-anchor" href="#象曰。频巽之吝。志穷也。" aria-label="Permalink to “象曰。频巽之吝。志穷也。”">​</a></h3><p>巽为心志。上无应。下乘阳。故曰志穷。</p><p>六四。悔亡。田获三品。</p><p>当位承阳。故悔亡。伏震为田猎。兑羊离牛巽豕。故田获三品。离卦数三也。凡阴遇重阳多吉。</p><h3 id="象曰。田获三品。有功也。" tabindex="-1">象曰。田获三品。有功也。 <a class="header-anchor" href="#象曰。田获三品。有功也。" aria-label="Permalink to “象曰。田获三品。有功也。”">​</a></h3><p>有所获。故有功。</p><p>九五。贞吉。悔亡。无不利。无初有终。先庚三日。后度三日。吉。</p><p>九五得位。下孚于阴。故贞吉悔亡。巽为利。故无不利。震巽相反复。无初者。言巽之初为震。震纳庚。一爻当一日。故曰先庚三日。今震究为龚。故无初。有终者。言巽之究仍为震。终即后也。故曰后庚三日。以其终为震。故曰有终。震阳复故吉。先庚三日。言巽之先。后庚三日。言巽之究。与蛊之先甲三日。后甲三日义同。无初有终。与蛊之终则有始义亦同。</p><h3 id="象曰。九五之吉。位正中也。" tabindex="-1">象曰。九五之吉。位正中也。 <a class="header-anchor" href="#象曰。九五之吉。位正中也。" aria-label="Permalink to “象曰。九五之吉。位正中也。”">​</a></h3><p>九五既中且正。故吉。</p><p>上九。巽在床下。丧其资斧。贞凶。</p><p>巽顺也。谓四。巽在床下。言顺我者在下。上九失其辅助。故曰丧其资斧。斧辅通用。兑为斧亦为辅。上卦兑覆。故曰丧失也。说详旅卦。</p><h3 id="象曰。巽在床下。上穷也。丧其资斧。正手凶也。" tabindex="-1">象曰。巽在床下。上穷也。丧其资斧。正手凶也。 <a class="header-anchor" href="#象曰。巽在床下。上穷也。丧其资斧。正手凶也。" aria-label="Permalink to “象曰。巽在床下。上穷也。丧其资斧。正手凶也。”">​</a></h3><p>九穷于上而下挠。故贞凶。象仍释贞为正。其义不协。</p>',30)])])}const f=e(s,[["render",h]]);export{_ as __pageData,f as default};
